query DarpanShopifyOrderLineUnitsByDateWindow {
  orders(query: "created_at:>='2026-08-01T00:00:00Z' created_at:<'2026-08-02T00:00:00Z'", sortKey: CREATED_AT) {
    edges {
      node {
        createdAt
        id
        legacyResourceId
        lineItems {
          edges {
            node {
              currentQuantity
              id
              name
              quantity
              sku
              unfulfilledQuantity
            }
          }
        }
        name
        returnStatus
        sourceName
      }
    }
  }
}
